/**
 * Real demo vehicle photos (Wikimedia Commons, freely licensed), bundled in /public/demo-cars.
 * Each entry keeps its author, licence and source page so credits can be shown in the gallery.
 * Generated by a one-off script; edit by hand if you swap a photo.
 */
export interface DemoPhoto {
  file: string;
  author: string;
  license: string;
  licenseUrl: string;
  source: string;
}

export interface DemoModelPhotos {
  /** Colour of the car in the photos; the demo vehicle uses it so data matches the picture. */
  color: string;
  photos: DemoPhoto[];
}

